      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0002_F04",
        "to_fact_id": "EP_0002_F03",
        "metric": "gross_margin",
        "from_period": {
          "label": "FY2024",
          "start": "2023-07-01",
          "end": "2024-06-30"
